export const messageRows = rows;
export function translate(locale:Locale,key:string,vars?:Record<string,string|number>){
  const values=rows[key]?.split('|');
  let value=values?.[locales.indexOf(locale)]??values?.[0]??key;
  if(vars)for(const [k,v]of Object.entries(vars))value=value.replaceAll('{'+k+'}',String(v));
  return value;
}
